// Builds app/research_lab/web/static/vendor/tiptap-editor.min.js and its licence file.
//
//   cd scripts/vendor/editor
//   npm ci --ignore-scripts      # exact versions from package-lock.json, no install scripts
//   npm run build
//
// The output is committed; the app itself never runs node and never loads a CDN.
// `vendor/` is in the root .gitignore, so new files in this folder need `git add -f`.
import { build } from 'esbuild'
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const staticVendor = resolve(here, '../../../app/research_lab/web/static/vendor')
const outfile = join(staticVendor, 'tiptap-editor.min.js')
const licenceFile = join(staticVendor, 'tiptap-editor.LICENSES.txt')

const manifest = JSON.parse(readFileSync(join(here, 'package.json'), 'utf8'))
const pkgJson = name => JSON.parse(readFileSync(join(here, 'node_modules', name, 'package.json'), 'utf8'))
const versions = Object.fromEntries(Object.keys(manifest.dependencies).map(name => [name, pkgJson(name).version]))
for (const [name, wanted] of Object.entries(manifest.dependencies)) {
  if (versions[name] !== wanted) throw new Error(`${name} is ${versions[name]}, package.json pins ${wanted}: run npm ci`)
}

const banner = `/*! RLEditor — TipTap ${versions['@tiptap/core']}, markdown-it ${versions['markdown-it']}, ` +
  `prosemirror-markdown ${versions['prosemirror-markdown']}. MIT-licensed parts; full texts in tiptap-editor.LICENSES.txt. ` +
  `Built by scripts/vendor/editor/build.mjs. */`

const result = await build({
  entryPoints: [join(here, 'entry.mjs')],
  outfile,
  bundle: true,
  minify: true,
  format: 'iife',
  globalName: 'RLEditor',
  target: ['safari16', 'chrome110', 'firefox110'],
  charset: 'utf8',
  legalComments: 'none',          // every bundled package's licence goes to the .LICENSES.txt file instead
  banner: { js: banner },
  define: { __RL_EDITOR_VERSIONS__: JSON.stringify(versions) },
  metafile: true,
  logLevel: 'warning',
})

// One licence entry per package that actually ended up in the bundle.
const used = new Map()
for (const input of Object.keys(result.metafile.inputs)) {
  const m = input.match(/node_modules\/((?:@[^/]+\/)?[^/]+)\//)
  if (m && !used.has(m[1])) used.set(m[1], join(here, 'node_modules', m[1]))
}
const licenceText = dir => {
  const name = readdirSync(dir).find(f => /^(licen[cs]e|copying)/i.test(f) && statSync(join(dir, f)).isFile())
  return name ? readFileSync(join(dir, name), 'utf8').trim() : null
}
const sections = [...used.keys()].sort().map(name => {
  const pkg = pkgJson(name)
  const text = licenceText(used.get(name))
  if (!text) throw new Error(`${name} ships no licence file; add its licence text by hand before bundling it`)
  return `${'='.repeat(78)}\n${name} ${pkg.version} (${pkg.license})\n${'='.repeat(78)}\n${text}\n`
})
writeFileSync(licenceFile, [
  'Third-party software bundled in tiptap-editor.min.js',
  `Generated by scripts/vendor/editor/build.mjs; ${used.size} packages.`,
  '',
  ...sections,
].join('\n'))

const kb = n => `${(n / 1024).toFixed(0)} KB`
const size = statSync(outfile).size
console.log(`${relative(process.cwd(), outfile)}  ${kb(size)}  (${used.size} packages)`)
if (existsSync(licenceFile)) console.log(`${relative(process.cwd(), licenceFile)}`)
